// 把 n8n 的錯誤資訊整理成一則 LINE 訊息。
// 推播對象由環境變數 N8N_ALERT_LINE_TARGET 指定（管理者的 User ID 或內部群組的 Group ID）。
const target = $env.N8N_ALERT_LINE_TARGET;
if (!target) {
  throw new Error('環境變數 N8N_ALERT_LINE_TARGET 未設定，無法推播錯誤通知');
}

const e = $json.execution || {};
const w = $json.workflow || {};

const when = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Taipei' });
const msg = (e.error?.message || '未知錯誤').slice(0, 300);

const lines = [
  '⚠️ LINE 助理系統發生錯誤',
  '',
  `時間：${when}`,
  `工作流：${w.name || '未知'}`,
  `失敗節點：${e.lastNodeExecuted || '未知'}`,
  '',
  `錯誤訊息：${msg}`,
];
if (e.url) lines.push('', `執行紀錄：${e.url}`);

return [{
  json: {
    pushPayload: {
      to: target,
      messages: [{ type: 'text', text: lines.join('\n').slice(0, 4900) }],
    },
  },
}];
